From 90d70baef5a0f3a843c28099107eee8ff9cd4c2f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:20:53 +0100
Subject: [PATCH] desktoppackage/configuration: Offer Auto hide in Tablet Mode
 for panels

The panel settings only listed visibility modes that apply all the time.
Add the new Auto hide in Tablet Mode entry to the Visibility combobox so
the panel can hide in Tablet Mode only and stay visible otherwise.

BUG: 517517
---
 .../contents/configuration/PanelConfiguration.qml    | 12 +++++++++---
 1 file changed, 9 insertions(+), 3 deletions(-)

diff --git a/desktoppackage/contents/configuration/PanelConfiguration.qml b/desktoppackage/contents/configuration/PanelConfiguration.qml
index cb897a1f04..063e7236a8 100644
--- a/desktoppackage/contents/configuration/PanelConfiguration.qml
+++ b/desktoppackage/contents/configuration/PanelConfiguration.qml
@@ -379,7 +379,7 @@ ColumnLayout {
             PanelRepresentation {
                 id: visibilityRepresentation
                 Layout.alignment: Qt.AlignHCenter
-                sunkenPanel: autoHideBox.previewIndex == 1 || autoHideBox.previewIndex == 2
+                sunkenPanel: autoHideBox.previewIndex == 1 || autoHideBox.previewIndex == 2 || autoHideBox.previewIndex == 4
                 onClicked: autoHideBox.popup.visible = true
                 windowVisible: true
                 panelReservesSpace: autoHideBox.previewIndex == 0
@@ -394,11 +394,12 @@ ColumnLayout {
                     i18ndc("plasma_shell_org.kde.plasma.desktop", "@item:inlistbox", "Auto hide"),
                     i18ndc("plasma_shell_org.kde.plasma.desktop", "@item:inlistbox", "Dodge windows"),
                     i18ndc("plasma_shell_org.kde.plasma.desktop", "@item:inlistbox", "Windows go below"),
+                    i18ndc("plasma_shell_org.kde.plasma.desktop", "@item:inlistbox", "Auto hide in Tablet Mode"),
                 ]
                 onPreviewIndexChanged: {
                     if (previewIndex == 0 || previewIndex == 3) {
                         visibilityRepresentation.maximizeWindow()
-                    } else if (previewIndex == 1) {
+                    } else if (previewIndex == 1 || previewIndex == 4) {
                         visibilityRepresentation.hidePanel()
                     } else if (previewIndex == 2) {
                         visibilityRepresentation.dodgePanel()
@@ -407,13 +408,15 @@ ColumnLayout {
                 Layout.alignment: Qt.AlignHCenter
                 Layout.minimumWidth: visibilityRepresentation.width
                 currentIndex: {
-                    switch (panel.visibilityMode) {
+                    switch (panel.configuredVisibilityMode) {
                         case Panel.AutoHide:
                             return 1;
                         case Panel.DodgeWindows:
                             return 2;
                         case Panel.WindowsGoBelow:
                             return 3;
+                        case Panel.AutoHideInTabletMode:
+                            return 4;
                         case Panel.NormalPanel:
                         default:
                             return 0;
@@ -430,6 +433,9 @@ ColumnLayout {
                         case 3:
                             panel.visibilityMode = Panel.WindowsGoBelow;
                             break;
+                        case 4:
+                            panel.visibilityMode = Panel.AutoHideInTabletMode;
+                            break;
                         case 0:
                         default:
                             panel.visibilityMode = Panel.NormalPanel;
-- 
2.53.0

From 96ea8e35ba34ebc87261479c48427032861bc901 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:20:52 +0100
Subject: [PATCH] shell/panelview: Add an Auto hide in Tablet Mode visibility
 mode

Panels could only auto hide all the time, so tablet users had to choose
between a panel in the way and one that also hides on the desktop. The
new mode auto hides in Tablet Mode and is always visible otherwise.

BUG: 517517
---
 shell/panelview.cpp       | 35 +++++++++++++++++++++++++++--------
 shell/panelview.h         |  8 ++++++++
 shell/scripting/panel.cpp |  7 ++++++-
 shell/shellcorona.cpp     | 32 +++++++++++++++++++++++++++++++-
 shell/shellcorona.h       |  7 +++++++
 5 files changed, 79 insertions(+), 10 deletions(-)

diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..bb3547db81 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -89,6 +89,11 @@ PanelView::PanelView(ShellCorona *corona, QScreen *targetScreen, QWindow *parent
     connect(&m_unhideTimer, &QTimer::timeout, this, &PanelView::restoreAutoHide);

     connect(m_corona, &Plasma::Corona::editModeChanged, this, &PanelView::restoreAutoHide);
+    connect(m_corona, &ShellCorona::tabletModeChanged, this, [this] {
+        if (m_visibilityMode == AutoHideInTabletMode && containment()) {
+            applyVisibilityMode();
+        }
+    });

     m_lastScreen = targetScreen;
     connect(this, &PanelView::containmentChanged, this, &PanelView::refreshContainment);
@@ -459,17 +464,22 @@ void PanelView::setVisibilityMode(PanelView::VisibilityMode mode)

     m_visibilityMode = mode;

-    disconnect(containment(), &Plasma::Applet::activated, this, &PanelView::showTemporarily);
-    if (edgeActivated()) {
-        connect(containment(), &Plasma::Applet::activated, this, &PanelView::showTemporarily);
-    }
-
     if (hasConfig()) {
         // panelVisibility is not resolution dependent, don't write to Defaults
         resolutionIndependentConfig().writeEntry("panelVisibility", (int)mode);
         m_corona->requestApplicationConfigSync();
     }

+    applyVisibilityMode();
+}
+
+void PanelView::applyVisibilityMode()
+{
+    disconnect(containment(), &Plasma::Applet::activated, this, &PanelView::showTemporarily);
+    if (edgeActivated()) {
+        connect(containment(), &Plasma::Applet::activated, this, &PanelView::showTemporarily);
+    }
+
     updateExclusiveZone();

     Q_EMIT visibilityModeChanged();
@@ -478,6 +488,14 @@ void PanelView::setVisibilityMode(PanelView::VisibilityMode mode)
 }

 PanelView::VisibilityMode PanelView::visibilityMode() const
+{
+    if (m_visibilityMode == AutoHideInTabletMode) {
+        return m_corona->isTabletMode() ? AutoHide : NormalPanel;
+    }
+    return m_visibilityMode;
+}
+
+PanelView::VisibilityMode PanelView::configuredVisibilityMode() const
 {
     return m_visibilityMode;
 }
@@ -981,7 +999,7 @@ void PanelView::restoreAutoHide()

 void PanelView::setAutoHideEnabled(bool enabled)
 {
-    if (m_visibilityMode == VisibilityMode::AutoHide || (m_visibilityMode == VisibilityMode::DodgeWindows && m_touchingWindow)) {
+    if (visibilityMode() == VisibilityMode::AutoHide || (visibilityMode() == VisibilityMode::DodgeWindows && m_touchingWindow)) {
         if (!m_autoHideScreenEdge) {
             m_autoHideScreenEdge = AutoHideScreenEdge::create(this);
         }
@@ -1463,7 +1481,7 @@ void PanelView::updateExclusiveZone()
         return;
     }

-    switch (m_visibilityMode) {
+    switch (visibilityMode()) {
     case NormalPanel:
         if (m_corona->shouldPanelReserveSpace(this)) {
             m_layerWindow->setExclusiveZone(thickness());
@@ -1472,6 +1490,7 @@ void PanelView::updateExclusiveZone()
         }
         break;
     case AutoHide:
+    case AutoHideInTabletMode:
     case DodgeWindows:
     case WindowsGoBelow:
         m_layerWindow->setExclusiveZone(-1);
@@ -1654,7 +1673,7 @@ void PanelView::screenDestroyed(QObject *)

 bool PanelView::edgeActivated() const
 {
-    return m_visibilityMode == PanelView::AutoHide || m_visibilityMode == PanelView::DodgeWindows;
+    return visibilityMode() == PanelView::AutoHide || visibilityMode() == PanelView::DodgeWindows;
 }

 void PanelView::updateEnabledBorders()
diff --git a/shell/panelview.h b/shell/panelview.h
index eb276bf7f6..22677bc53c 100644
--- a/shell/panelview.h
+++ b/shell/panelview.h
@@ -92,6 +92,11 @@ class PanelView : public PlasmaQuick::ContainmentView
      */
     Q_PROPERTY(VisibilityMode visibilityMode READ visibilityMode WRITE setVisibilityMode NOTIFY visibilityModeChanged)

+    /**
+     *  the visibility mode set by the user, which can be AutoHideInTabletMode
+     */
+    Q_PROPERTY(VisibilityMode configuredVisibilityMode READ configuredVisibilityMode WRITE setVisibilityMode NOTIFY visibilityModeChanged)
+
     /**
      *  Property that determines how a panel's opacity behaves.
      *
@@ -148,6 +153,7 @@ public:
         AutoHide, /**the panel will be shownn only if the mouse cursor is on screen edges */
         DodgeWindows, /* the panel will be normally visible, but will hide if a window would cover it */
         WindowsGoBelow, /* the panel is always visible but will not reserve any space */
+        AutoHideInTabletMode, /* the panel behaves like AutoHide in Tablet Mode and like NormalPanel otherwise */
     };
     Q_ENUM(VisibilityMode)

@@ -210,6 +216,7 @@ public:
     KSvg::FrameSvg::EnabledBorders enabledBorders() const;

     VisibilityMode visibilityMode() const;
+    VisibilityMode configuredVisibilityMode() const;
     void setVisibilityMode(PanelView::VisibilityMode mode);

     PanelView::OpacityMode opacityMode() const;
@@ -293,6 +300,7 @@ protected Q_SLOTS:
     void showConfigurationInterface(Plasma::Applet *applet) override;

 private Q_SLOTS:
+    void applyVisibilityMode();
     void setAutoHideEnabled(bool autoHideEnabled);
     void showTemporarily();
     void refreshContainment();
diff --git a/shell/scripting/panel.cpp b/shell/scripting/panel.cpp
index b60a3f4275..da1207a34c 100644
--- a/shell/scripting/panel.cpp
+++ b/shell/scripting/panel.cpp
@@ -302,7 +302,7 @@ QString Panel::hiding() const
 {
     int visibility;
     if (panel()) {
-        visibility = panel()->visibilityMode();
+        visibility = panel()->configuredVisibilityMode();
     } else {
         visibility = panelConfig().parent().readEntry("panelVisibility", 0);
     }
@@ -314,6 +314,8 @@ QString Panel::hiding() const
         return u"autohide"_s;
     case PanelView::DodgeWindows:
         return u"dodgewindows"_s;
+    case PanelView::AutoHideInTabletMode:
+        return u"autohideintabletmode"_s;
     }
     return u"none"_s;
 }
@@ -330,6 +332,9 @@ void Panel::setHiding(const QString &mode)
     if (mode.compare(u"windowsgobelow", Qt::CaseInsensitive) == 0) {
         visibilityMode = PanelView::WindowsGoBelow;
     }
+    if (mode.compare(u"autohideintabletmode", Qt::CaseInsensitive) == 0) {
+        visibilityMode = PanelView::AutoHideInTabletMode;
+    }

     if (panel()) {
         panel()->setVisibilityMode(visibilityMode);
diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..76c8deb113 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -19,6 +19,7 @@
 #include <QDBusMetaType>
 #include <QDBusPendingCallWatcher>
 #include <QDBusReply>
+#include <QDBusVariant>
 #include <QDebug>
 #include <QFile>
 #include <QJsonArray>
@@ -165,6 +166,18 @@ void ShellCorona::init()
     QDBusConnection dbus = QDBusConnection::sessionBus();
     dbus.registerObject(QStringLiteral("/PlasmaShell"), this);

+    dbus.connect(u"org.kde.KWin"_s, u"/org/kde/KWin"_s, u"org.kde.KWin.TabletModeManager"_s, u"tabletModeChanged"_s, this, SLOT(setTabletMode(bool)));
+    auto tabletModeMessage = QDBusMessage::createMethodCall(u"org.kde.KWin"_s, u"/org/kde/KWin"_s, u"org.freedesktop.DBus.Properties"_s, u"Get"_s);
+    tabletModeMessage.setArguments({u"org.kde.KWin.TabletModeManager"_s, u"tabletMode"_s});
+    auto tabletModeWatcher = new QDBusPendingCallWatcher(dbus.asyncCall(tabletModeMessage), this);
+    connect(tabletModeWatcher, &QDBusPendingCallWatcher::finished, this, [this, tabletModeWatcher] {
+        tabletModeWatcher->deleteLater();
+        QDBusReply<QDBusVariant> reply = *tabletModeWatcher;
+        if (reply.isValid()) {
+            setTabletMode(reply.value().variant().toBool());
+        }
+    });
+
     // Look for theme config in plasmarc, if it isn't configured, take the theme from the
     // LookAndFeel package, if either is set, change the default theme

@@ -504,10 +517,13 @@ QByteArray ShellCorona::dumpCurrentLayoutJS() const
             panelJson.insert(u"floating"_s, view->floating());
             panelJson.insert(u"floatingApplets"_s, view->floatingApplets());

-            switch (view->visibilityMode()) {
+            switch (view->configuredVisibilityMode()) {
             case PanelView::AutoHide:
                 panelJson.insert(u"hiding", u"autohide"_s);
                 break;
+            case PanelView::AutoHideInTabletMode:
+                panelJson.insert(u"hiding", u"autohideintabletmode"_s);
+                break;
             case PanelView::DodgeWindows:
                 panelJson.insert(u"hiding", u"dodgewindows"_s);
                 break;
@@ -2943,6 +2959,20 @@ void ShellCorona::updateStruts()
     }
 }

+bool ShellCorona::isTabletMode() const
+{
+    return m_tabletMode;
+}
+
+void ShellCorona::setTabletMode(bool tabletMode)
+{
+    if (m_tabletMode == tabletMode) {
+        return;
+    }
+    m_tabletMode = tabletMode;
+    Q_EMIT tabletModeChanged();
+}
+
 void ShellCorona::activateLauncherMenu()
 {
     auto message = QDBusMessage::createMethodCall(u"org.kde.KWin"_s, u"/KWin"_s, u"org.kde.KWin"_s, u"activeOutputName"_s);
diff --git a/shell/shellcorona.h b/shell/shellcorona.h
index a85cd9aa07..c296f9e98c 100644
--- a/shell/shellcorona.h
+++ b/shell/shellcorona.h
@@ -137,6 +137,8 @@ public:

     PanelView *panelBeingConfigured() const;

+    bool isTabletMode() const;
+
     Q_INVOKABLE bool enteredEditModeViaDesktop();

     Q_INVOKABLE bool isScreenUiReady(uint screen);
@@ -175,6 +177,7 @@ Q_SIGNALS:
     // Emitted after the new shell has loaded
     void shellChanged(const QString &shell);
     void screenUiReadyChanged(uint screen, bool ready);
+    void tabletModeChanged();

 public Q_SLOTS:
     /**
@@ -279,6 +282,9 @@ private Q_SLOTS:
     void handleScreenRemoved(QScreen *screen);
     void handleScreenOrderChanged(QList<QScreen *> screens);

+private Q_SLOTS:
+    void setTabletMode(bool tabletMode);
+
 private:
     void sanitizeScreenLayout(const QString &configFileName);
     void destroyDesktopsAndPanels();
@@ -319,6 +325,7 @@ private:

     bool m_blockRestorePreviousWindow = false;
     bool m_editModeShowedDesktop = false;
+    bool m_tabletMode = false;

     QTimer m_waitingPanelsTimer;
     QTimer m_appConfigSyncTimer;
